#!/bin/bash
set -euo pipefail
umask 077
P=/scratch/jjyeung/orch_n30/lever7/nfa/fix1/t/psim/P
test -e "$P/PACKAGE.json"
test ! -e "$P/a/70.txt"
q=$(squeue -u jjyeung -h -o '%j' | grep '^a15_cot_apc8b836b4ae536' || true)
test -z "$q"
/scratch/jjyeung/envs/p1cpu/bin/python -I -s -B - "$P" <<'PY'
import base64,gzip,hashlib,json,os,sys
from pathlib import Path
p=Path(sys.argv[1]);spec=json.loads('{"BATCH.sh": {"mode": 448, "new": "02f6fe370f2dd53b874d5525badb84154dc515689e0e792b6c85fdf8e7141ab4", "old": "5fa46bf51b0eb0ea6046e463eb29c82cdfe7cbb998e7fab3a1e5043d9a2a8df1"}, "PACKAGE.json": {"mode": 384, "new": "b7a04c51cd5c3db16b8fa71cf2c51f38d8fc6b1a5c42f0f92f9bc7eb2efafe01", "old": "c8a251210c0bc960e85f26ff76aa902759dcc21107f61c37384ff7cb4c2e72a8"}, "a/6.py": {"mode": 384, "new": "7c7b9216301e55c1a1e51a03486fb24b09abd095c78742a328d1eda4acf98c47", "old": "92de4cc43789b451eac12840f4faf0088d01fb88904aa73b2c8eac61eab22ce5"}}');h=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
order=['a/6.py', 'BATCH.sh', 'PACKAGE.json']
blobs={'a/6.py':base64.b64decode(''),'BATCH.sh':base64.b64decode(''),'PACKAGE.json':base64.b64decode('')}
for n in order:
    if h(p/n)!=spec[n]['old']:raise SystemExit('E81 '+n+' is not the placed pre-fix file')
    if os.path.lexists(str(p/n)+'.pre1'):raise SystemExit('E82 '+n+'.pre1 exists')
if os.path.lexists(str(p/'2.json')+'.pre1'):raise SystemExit('E82 2.json.pre1 exists')
for n in order:
    data=gzip.decompress(blobs[n])
    if hashlib.sha256(data).hexdigest()!=spec[n]['new']:raise SystemExit('E83 '+n)
    os.rename(p/n,str(p/n)+'.pre1')
    fd=os.open(p/n,os.O_WRONLY|os.O_CREAT|os.O_EXCL,spec[n]['mode'])
    with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
    got=h(p/n)
    if got!=spec[n]['new'] or h(Path(str(p/n)+'.pre1'))!=spec[n]['old']:raise SystemExit('E84 '+n)
    print(n,got,'kept',n+'.pre1',spec[n]['old'])
if (p/'2.json').exists():
    os.rename(p/'2.json',str(p/'2.json')+'.pre1');print('2.json moved to 2.json.pre1; run o_check.sh next')
pins=json.loads((p/'PACKAGE.json').read_text())['files']
bad=[n for n,v in pins.items() if h(p/n)!=v]
if bad:raise SystemExit('E85 pins differ: '+' '.join(bad))
print('pins ok',len(pins))
PY
